                raise GroupNotFoundError(f"{group_name} not found in {names[0]}")
            else:
                warnings.warn(f"{group_name} not found in {names[0]}")
                continue
        coeff = float(coeff) if coeff not in ["+", "-"] else 1.0 if coeff == "+" else -1.0
        A[i] += coeff * group_names[group_name]

    # Handle the sum-to-one constraint
    if sum_to_one:
        if not np.isclose(rhs, 1):
            raise EquationToMatrixError("When 'sum_to_one' is True, the right-hand side of the equation must be 1.")
