                        continue
                left_matrix[i, :] += sign * coeff * groups[group_idx, :]
            else:
                raise EquationToMatrixError(f"Invalid token '{token}' in equation {i}.")

    right_matrix[i] = rhs

return left_matrix, right_matrix

