connection_id = getattr(message, 'connection_id', DEFAULT_CONNECTION_ID)
with self.lock:
    if connection_id not in self.connections:
        self.connections[connection_id] = self.server.create_connection(connection_id)

connection = self.connections[connection_id]

if isinstance(message, SendMessage):
    message.data = connection.c2s(message.data)
elif isinstance(message, RecvMessage):
    message.data = connection.s2c(message.data)
elif isinstance(message, CloseMessage):
    with self.lock:
        if connection_id in self.connections:
            connection.close()
            if self.config['autoCloseConnections']:
                del self.connections[connection_id]

# The function does not return anything as it modifies the message object in place.

# First, close all active connections
with self.lock:
    for connection_id, connection in list(self.connections.items()):
        try:
            connection.close()
        except Exception as e:
            self.logger.error(f"Error closing connection {connection_id}: {e}")
        finally:
            # Remove the connection from the dictionary
            self.connections.pop(connection_id, None)

# Then, stop the server if it's running
if self.server:
    try:
        self.server.stop()
    except Exception as e:
        self.logger.error(f"Error stopping server: {e}")
    finally:
