    code_path.write_text(user_code + test_code, encoding="utf-8")

    # Run Pyright type checker as a subprocess
    result = subprocess.run(
        ["pyright", str(code_path), "--outputjson"],
        capture_output=True,
        text=True,
    )

    # Parse the JSON output from Pyright
    try:
        pyright_output = result.stdout
        output_json = json.loads(pyright_output)
        errors = output_json.get("generalDiagnostics", [])
    except json.JSONDecodeError:
        return TypeCheckResult(
            message="Failed to parse Pyright output.",
            passed=False,
            debug_info={"pyright_output": pyright_output},
        )

    # Check for expected type errors
    expected_errors = set()
    for line in user_code.splitlines():
        if cls.EXPECT_ERROR_COMMENT in line:
            line_number = line.split(':')[0]
            expected_errors.add(int(line_number))

    # Check if there are unexpected errors or if expected errors are missing
    actual_errors = set()
    for error in errors:
        if error.get("severity") == "error":
            line_number = error["range"]["start"]["line"] + 1  # Pyright line numbers are 0-based
            actual_errors.add(line_number)

    unexpected_errors = actual_errors - expected_errors
    missing_errors = expected_errors - actual_errors

    # Construct the result message
    if unexpected_errors or missing_errors:
        messages = []
        if unexpected_errors:
            messages.append(f"Unexpected errors at lines: {sorted(unexpected_errors)}.")
        if missing_errors:
            messages.append(f"Expected errors missing at lines: {sorted(missing_errors)}.")
        message = "Type check failed. " + " ".join(messages)
        passed = False
    else:
        message = "Type check passed."
        passed = True

    return TypeCheckResult(
        message=message,
        passed=passed,
        debug_info={
            "unexpected_errors": sorted(unexpected_errors),
            "missing_errors": sorted(missing_errors),
            "pyright_output": pyright_output,
        },
    )

