# Resize the rendering context to match the camera's dimensions
eglctx.resize(camera.width, camera.height)

# Set the OpenGL viewport to the camera's dimensions
gl.glViewport(0, 0, camera.width, camera.height)

# Set common OpenGL options for rendering
common_opengl_options()

# Use the appropriate shader program based on the mesh's render type
if self.render_type == Mesh.RenderType.POINTS:
    use_gl_program(self.point_program)
else:
    use_gl_program(self.mesh_program)

# Set the uniforms for the shader program
for uniform_name, uniform_value in self.uniforms.items():
    location = gl.glGetUniformLocation(self.mesh_program, uniform_name)
    if isinstance(uniform_value, (int, float)):
        gl.glUniform1f(location, uniform_value)
    elif isinstance(uniform_value, (glm.vec2, glm.vec3, glm.vec4)):
        if len(uniform_value) == 2:
            gl.glUniform2fv(location, 1, glm.value_ptr(uniform_value))
        elif len(uniform_value) == 3:
            gl.glUniform3fv(location, 1, glm.value_ptr(uniform_value))
        elif len(uniform_value) == 4:
            gl.glUniform4fv(location, 1, glm.value_ptr(uniform_value))
    elif isinstance(uniform_value, (glm.mat2x3, glm.mat3, glm.mat4, glm.mat4x3)):
