    if dir_path.startswith("s3://"):
        if not _BOTO3_AVAILABLE:
            raise ImportError("boto3 must be installed to handle s3:// paths.")
        return Dir(url=dir_path)
    # Check if the path is a Lightning Studio project path
    elif dir_path.startswith("/lightning/"):
        if not _LIGHTNING_SDK_AVAILABLE:
            raise ImportError("lightning_sdk must be installed to handle /lightning/ paths.")
        return Dir(url=dir_path)
    else:
        # Assume it's a local file path
        local_path = Path(dir_path).resolve()
        return Dir(path=str(local_path))

raise TypeError("dir_path must be a string or Dir object.")
